def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0
    desperate_pressure = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 140:
                    rich_pressure += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                desperate_pressure += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    low_supply = supply <= 17.0
    very_low_supply = supply <= 16.0
    high_supply = supply >= 22.0

    emergency = hp <= 2 or no_water_days >= 2
    danger = hp <= 4 or no_water_days >= 1

    if emergency:
        bid = max(95.0, high_prev + 2.0)
        if very_low_supply:
            bid = max(bid, 120.0)
        return float(min(budget, bid))

    if danger:
        if high_prev >= 150.0:
            bid = 88.0 if not very_low_supply else 108.0
        else:
            bid = max(72.0, min(110.0, high_prev + 3.0))
        return float(min(budget, bid))

    if high_supply and rich_pressure >= 1:
        bid = 8.0
    elif low_supply:
        if high_prev >= 150.0:
            bid = 22.0
        else:
            bid = max(26.0, min(60.0, high_prev * 0.55 + 4.0))
    else:
        if high_prev >= 150.0:
            bid = 12.0
        elif high_prev >= 90.0:
            bid = 24.0
        elif high_prev > 0.0:
            bid = max(20.0, min(48.0, high_prev * 0.6 + 2.0))
        else:
            bid = 21.0

    if desperate_pressure >= 2 and not high_supply:
        bid += 8.0
    elif desperate_pressure == 1 and low_supply:
        bid += 4.0

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.9

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    # 1. Initialize bid based on my HP urgency
    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 1.25  # Desperate: bid very high
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 1.05  # Urgent: bid high
    else:
        bid = DAILY_SALARY * 0.85  # Normal: competitive bid

    # 2. Check for Eric and adjust bid accordingly
    eric_status = opponents_status.get('Eric')
    eric_is_alive = eric_status and eric_status['alive']
    eric_last_bid = 0
    if eric_is_alive and eric_status.get('previous_trace'):
        eric_last_bid = eric_status['previous_trace'].get('bid', 0.0)

    if eric_is_alive:
        # Eric is a strong, aggressive opponent. We must react to his high bids.
        if eric_last_bid > DAILY_SALARY * 0.95: # If Eric bid very aggressively before
            bid = max(bid, eric_last_bid + 5.0) # Try to outbid him by a margin
        else:
            # Eric is alive but didn't bid high last time, or no trace. Assume he will be aggressive.
            bid = max(bid, DAILY_SALARY * 1.1) # Be proactively aggressive against Eric
    else:
        # Eric is not alive. Competition is likely less fierce.
        highest_other_bid = 0.0
        num_other_alive_opponents = 0
        for opp_id, opp_data in opponents_status.items():
            if opp_id != 'Eric' and opp_data['alive']:
                num_other_alive_opponents += 1
                if opp_data.get('previous_trace'):
                    other_bid = opp_data['previous_trace'].get('bid', 0.0)
                    highest_other_bid = max(highest_other_bid, other_bid)

        if num_other_alive_opponents > 0:
            if highest_other_bid > DAILY_SALARY * 0.7:
                bid = max(bid, highest_other_bid + 2.0) # React to other strong bids
            else:
                bid = max(bid, DAILY_SALARY * 0.75) # Default competitive bid against other opponents
        else:
            # No active opponents remaining
            bid = DAILY_SALARY * 0.3 # Minimal bid to secure water cheaply

    # 3. Ensure bid does not exceed current budget and is at least a minimal amount
    bid = min(bid, my_status['budget'])
    if bid <= 0:
        return 0.01 # Always bid a minimal amount to stay in the game if budget is zero or negative

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])
    # Base bid: 60% of daily salary
    base_bid = DAILY_SALARY * 0.6
    # Adjust based on personal health and water needs
    if my_status['hp'] <= 3:
        base_bid = DAILY_SALARY * 0.9
    elif my_status['no_water_days'] >= 1:
        base_bid = DAILY_SALARY * 0.8
    # Respond to high previous bids
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY * 0.7:
            target = max_prev + 1.5
            if target > DAILY_SALARY * 0.95:
                target = DAILY_SALARY * 0.95
            base_bid = max(base_bid, target)
    # Ensure bid does not exceed budget
    bid = min(base_bid, my_status['budget'])
    if bid < 1:
        bid = 0
    return bid
